    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 12px;
    padding: 12px 14px;
    display: flex;
    align-items: center;
    gap: 12px;
  }
  li.item .fav {
    width: 30px; height: 30px; flex: 0 0 auto;
    border-radius: 7px;
    background: #eef2ff;
    display: flex; align-items: center; justify-content: center;
    font-size: 14px; color: var(--accent);
    font-weight: 700;
  }
  li.item .body { min-width: 0; flex: 1 1 auto; }
  li.item .title {
    font-size: 15px; font-weight: 600;
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  }
  li.item .url {
    font-size: 13px; color: var(--muted);
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  }
  li.item a { color: inherit; text-decoration: none; }
  li.item a:hover .title { text-decoration: underline; }

  .empty {
    text-align: center;
    color: var(--muted);
    padding: 48px 16px;
    border: 1px dashed var(--line);
    border-radius: 12px;
    background: var(--card);
  }
  .empty .big { font-size: 32px; margin-bottom: 8px; }

  .flash {
    background: #ecfdf5;
    border: 1px solid #a7f3d0;
    color: #065f46;
    padding: 10px 12px;
    border-radius: 9px;
    font-size: 14px;
    margin-bottom: 12px;
    display: none;
  }
</style>
</head>
<body>
<header>
  <h1>My Bookmarks</h1>
  <p>Your one place to save and find links.</p>
</header>
<main>
  <form class="saver" id="saver" autocomplete="off">
    <input type="url" id="urlInput" placeholder="Paste a link here…  e.g. https://example.com/article" required />
    <button type="submit">Save</button>
  </form>

  <div class="flash" id="flash"></div>
  <p class="count" id="count"></p>
  <ul class="list" id="list"></ul>
</main>

<script>
  var STORE = "bm_proto_v1";
  function load() {
    try { return JSON.parse(localStorage.getItem(STORE)) || []; }
    catch (e) { return []; }
  }
  function save(items) { localStorage.setItem(STORE, JSON.stringify(items)); }

  function labelFor(url) {
    try {
      var u = new URL(url);
      var host = u.hostname.replace(/^www\./, "");
      var path = (u.pathname && u.pathname !== "/") ? u.pathname : "";
      // Derive a readable label from the last path segment, else the host.
      var seg = path.split("/").filter(Boolean).pop();
      if (seg) {
        seg = decodeURIComponent(seg).replace(/[-_]+/g, " ").replace(/\.\w+$/, "");
        seg = seg.charAt(0).toUpperCase() + seg.slice(1);
        return seg + " — " + host;
      }
      return host;
    } catch (e) { return url; }
  }
  function initialFor(url) {
    try { return new URL(url).hostname.replace(/^www\./, "").charAt(0).toUpperCase(); }
    catch (e) { return "•"; }
  }

  function render() {
    var items = load();
    var list = document.getElementById("list");
    var count = document.getElementById("count");
    list.innerHTML = "";
    if (items.length === 0) {
      count.textContent = "";
      list.innerHTML =
        '<div class="empty"><div class="big">🔖</div>' +
        'Nothing saved yet. Paste a link above and press Save.</div>';
      return;
    }
    count.textContent = items.length + (items.length === 1 ? " saved link" : " saved links");
    items.forEach(function (it) {
      var li = document.createElement("li");
      li.className = "item";
      li.innerHTML =
        '<div class="fav">' + initialFor(it.url) + '</div>' +
        '<div class="body"><a href="' + it.url + '" target="_blank" rel="noopener">' +
        '<div class="title"></div><div class="url"></div></a></div>';
      li.querySelector(".title").textContent = it.label;
      li.querySelector(".url").textContent = it.url;
      list.appendChild(li);
    });
  }

  function flash(msg) {
    var f = document.getElementById("flash");
    f.textContent = msg;
    f.style.display = "block";
    clearTimeout(f._t);
    f._t = setTimeout(function () { f.style.display = "none"; }, 2600);
  }

  document.getElementById("saver").addEventListener("submit", function (e) {
    e.preventDefault();
    var input = document.getElementById("urlInput");
    var url = input.value.trim();
    if (!url) return;
    var items = load();
    items.unshift({ url: url, label: labelFor(url), savedAt: Date.now() });
    save(items);
    input.value = "";
    render();
    flash("Saved.");
    input.focus();
  });

  render();
  document.body.setAttribute("data-harness-ready", "true");
</script>
</body>
</html>

